<h1 class="h">Sklad</h1><div class="sub">Produkty, materiál, ceny a minimální zásoba.</div>
<div class="card"><form class="form" method="post" action="/products/save"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="row"><div class="field"><label>Název</label><input name="name" required></div><div class="field"><label>SKU</label><input name="sku"></div></div><div class="row"><div class="field"><label>Nákupní cena</label><input name="purchase_price" type="number" step=".01"></div><div class="field"><label>Prodejní cena</label><input name="sale_price" type="number" step=".01"></div></div><div class="row"><div class="field"><label>Sklad</label><input name="stock" type="number" step=".01"></div><div class="field"><label>Minimální zásoba</label><input name="min_stock" type="number" step=".01"></div></div><button class="btn primary">Přidat položku</button></form></div><div style="height:16px"></div>
<div class="card tablewrap"><table class="table"><tr><th>Produkt</th><th>SKU</th><th>Nákup</th><th>Prodej</th><th>Sklad</th><th>Upozornění</th><th></th></tr><?php foreach($products as $p):?><tr><td><b><?=View::e($p['name'])?></b></td><td><?=View::e($p['sku'])?></td><td><?=View::money($p['purchase_price'])?></td><td><?=View::money($p['sale_price'])?></td><td><?=View::e($p['stock'])?> <?=View::e($p['unit'])?></td><td><?php if($p['stock']<=$p['min_stock']):?><span class="badge danger">Doplnit</span><?php endif;?></td><td><a class="btn" href="/products/<?=$p['id']?>/edit">Upravit</a></td></tr><?php endforeach;?></table></div>
<div class="card" style="margin-top:16px"><h3>Skladový pohyb</h3><form class="row" method="post" action="/products/move"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="field"><label>Produkt</label><select name="product_id"><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=View::e($p['name'])?> (<?=View::e($p['stock'])?> <?=View::e($p['unit'])?>)</option><?php endforeach;?></select></div><div class="field"><label>Typ</label><select name="type"><option value="in">Příjem</option><option value="out">Výdej</option></select></div><div class="field"><label>Množství</label><input name="qty" type="number" step="0.01" min="0.01" required></div><div class="field"><label>Poznámka</label><input name="note"></div><button class="btn primary">Zapsat pohyb</button></form></div>
<div class="card" style="margin-top:16px"><h3>Inventura</h3><form class="row" method="post" action="/products/inventory-count"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><select name="product_id" required><option value="">Produkt</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=View::e($p['name'])?> (stav <?=View::e($p['stock'])?>)</option><?php endforeach;?></select><input name="counted_stock" type="number" step="0.01" placeholder="Skutečný stav" required><input name="note" placeholder="Poznámka"><button class="btn primary">Zapsat inventuru</button></form></div>
